import{_ as t,c as i,o as s,ae as a}from"./chunks/framework.BHrE6nLq.js";const h=JSON.parse('{"title":"Projects","description":"","frontmatter":{"layout":"doc","title":"Projects","nav":{"order":1}},"headers":[],"relativePath":"projects.md","filePath":"projects.md"}'),r={name:"projects.md"};function o(l,e,n,c,p,d){return s(),i("div",null,e[0]||(e[0]=[a('<h1 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h1><p><strong>Showcasing my research, projects, and technical insights</strong><br><em>Innovating through code, data, and scalable systems</em></p><hr><h2 id="explore-my-work" tabindex="-1">Explore My Work <a class="header-anchor" href="#explore-my-work" aria-label="Permalink to &quot;Explore My Work&quot;">​</a></h2><p>Dive into my project portfolio! Below, I’ve organized my creations into System Designs, SDKs, and Full Stack Applications. These projects reflect my drive to build scalable, impactful solutions—let’s see what I’ve crafted!</p><hr><h3 id="system-designs" tabindex="-1">System Designs <a class="header-anchor" href="#system-designs" aria-label="Permalink to &quot;System Designs&quot;">​</a></h3><p><em>Architecting for scale, performance, and real-world impact</em></p><ul><li><p><strong>BrandPulse</strong><br><em>Real-time social media monitoring at scale</em><br> An MVP processing 700,000 social media posts per second, delivering instant brand sentiment insights. Built with Node.js, Kafka, and InfluxDB, BrandPulse simulates a flood of tweets about &quot;SuperCoffee,&quot; proving my knack for designing scalable, high-performance systems.</p><ul><li>Protects revenue by detecting crises in seconds.</li><li>Boosts sales by amplifying positive trends fast.</li><li>Scales to handle global brand volumes effortlessly.<br><a href="/docs/brandpulse/"><strong>Explore →</strong></a></li></ul></li><li><p><strong>QuickLinker-ZeroRPM</strong><br><em>Zero infrastructure cost, infinite scalability</em><br> A high-performance URL shortener engineered for enterprise-scale traffic with minimal cost. Using Node.js, PostgreSQL, and Redis, this project showcases resilient system design with smart caching—delivering speed and scalability without breaking the bank.</p><ul><li>Cuts costs with lightweight, efficient tech.</li><li>Scales infinitely to meet massive demand.</li><li>Proves simplicity can power enterprise solutions.<br><a href="/docs/quicklinker-zeroRPM/"><strong>Explore →</strong></a></li></ul></li><li><p><em>(+9 more system designs in progress—watch this space!)</em></p></li></ul><hr><h3 id="sdks" tabindex="-1">SDKs <a class="header-anchor" href="#sdks" aria-label="Permalink to &quot;SDKs&quot;">​</a></h3><p><em>Empowering developers with powerful tools</em></p><ul><li><p><strong>Attestation SDK</strong><br><em>Managing digital payment commitments</em><br> A TypeScript SDK for handling digital payment commitments using hierarchical deterministic (HD) wallets and cryptographic attestations, following the BAFT Digital Ledger Payment Commitment protocol.</p><ul><li>Supports HD wallets with BIP32/BIP39 standards.</li><li>Ensures secure signatures with secp256k1.</li><li>Integrates with MetaMask, WalletConnect, and more.</li><li>Manages the full attestation lifecycle with state validation.<br><a href="/docs/attestify/"><strong>Explore →</strong></a></li></ul></li><li><p><strong>Chainly SDK</strong><br><em>Orchestrating complex workflows</em><br> A TypeScript SDK for automating workflows with task dependencies, streamlining execution, and enhancing error resilience. Chainly lets developers focus on business logic while it handles the heavy lifting.</p><ul><li>Automates task execution based on dependencies.</li><li>Adapts dynamically with conditional branching.</li><li>Offers retries, nested workflows, and event-driven triggers.</li><li>Separates logic from infrastructure for clarity.<br><a href="/"><strong>Explore →</strong></a></li></ul></li><li><p><em>(More SDKs coming soon—stay tuned for developer tools!)</em></p></li></ul><hr><h3 id="full-stack-applications" tabindex="-1">Full Stack Applications <a class="header-anchor" href="#full-stack-applications" aria-label="Permalink to &quot;Full Stack Applications&quot;">​</a></h3><p><em>End-to-end solutions with practical innovation</em></p><ul><li><p><strong>Project X</strong><br><em>Placeholder for future greatness</em><br> A full-stack app solving a real-world problem with a robust tech stack. Details coming soon!<br><a href="/"><strong>Explore →</strong></a></p></li><li><p><em>(+10 more full-stack projects to be added—structured similarly)</em></p></li></ul><hr><h2 id="want-more" tabindex="-1">Want More? <a class="header-anchor" href="#want-more" aria-label="Permalink to &quot;Want More?&quot;">​</a></h2><p><em>New projects are always brewing—keep an eye out for updates!</em></p>',20)]))}const g=t(r,[["render",o]]);export{h as __pageData,g as default};
